def gen(rng):
    def fmt(ops):
        return str(len(ops)) + '\n' + '\n'.join(f'{o} {v}' for o, v in ops)
    tests = [
        fmt([('random', 5)]),
        fmt([('remove', 3), ('search', 3), ('insert', 3), ('insert', 3), ('random', 0), ('remove', 3), ('random', 7)]),
        fmt([('insert', -1000000000), ('insert', 1000000000), ('random', 1000000000), ('remove', -1000000000), ('random', 999999999), ('search', 1000000000)]),
        fmt([('insert', i) for i in range(1, 6)] + [('remove', 1), ('random', 0), ('random', 4), ('remove', 5), ('random', 3)]),
    ]
    ops_pool = ['insert', 'insert', 'remove', 'search', 'random']
    for n, rng_v in ((6, 3), (10, 4), (15, 5), (20, 5), (25, 8), (30, 6), (30, 10), (35, 4), (40, 7), (40, 12)):
        ops = []
        for _ in range(n):
            o = rng.choice(ops_pool)
            v = rng.randint(0, 10**9) if o == 'random' else rng.randint(-rng_v, rng_v)
            ops.append((o, v))
        tests.append(fmt(ops))
    N = 40000
    def big(span):
        ops = []
        live = []
        for _ in range(N):
            r = rng.random()
            if r < 0.45 or not live:
                v = rng.randint(-span, span)
                live.append(v)
                ops.append(('insert', v))
            elif r < 0.7:
                v = live[rng.randrange(len(live))] if rng.random() < 0.8 else rng.randint(-span, span)
                ops.append(('remove', v))
            elif r < 0.85:
                ops.append(('search', rng.choice(live)))
            else:
                ops.append(('random', rng.randint(0, 10**9)))
        return ops
    tests.append(fmt(big(10**9)))
    tests.append(fmt(big(30000)))
    ops = [('insert', 10**9 - i) for i in range(20000)] + [('remove', 10**9 - i) for i in range(0, 20000, 2)] + [('random', rng.randint(0, 10**9)) for _ in range(N - 30000)]
    tests.append(fmt(ops))
    return tests
